import React, { useState, useEffect } from 'react';

const LeaderboardModal = ({ isOpen, onClose }) => {
  const [leaderboardData, setLeaderboardData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('topPlayers');

  useEffect(() => {
    if (isOpen) {
      const fetchLeaderboard = async () => {
        try {
          const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/stats/leaderboard`);
          const data = await response.json();

          // Ensure data is an array before setting state
          if (Array.isArray(data)) {
            setLeaderboardData(data);
          } else if (data && Array.isArray(data.leaderboard)) {
            // If the API returns an object with a leaderboard property that contains the array
            setLeaderboardData(data.leaderboard);
          } else {
            // Fallback to empty array if unexpected format
            setLeaderboardData([]);
          }

          setLoading(false);
        } catch (error) {
          console.error('Error fetching leaderboard:', error);
          setLeaderboardData([]);
          setLoading(false);
        }
      };

      fetchLeaderboard();
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const getTabContent = () => {
    if (loading) {
      return (
        <div className="loading-container" style={{ minHeight: '300px' }}>
          <div className="loading-spinner"></div>
          <p>Loading leaderboard...</p>
        </div>
      );
    }

    return (
      <div className="table-responsive">
        <table className="table">
          <thead>
            <tr>
              <th>Rank</th>
              <th>Player</th>
              <th>{activeTab === 'topPlayers' ? 'Balance' : activeTab === 'mostWins' ? 'Wins' : 'Streak'}</th>
              {activeTab !== 'highestStreak' && (
                <>
                  <th>Losses</th>
                  <th>Win Rate</th>
                </>
              )}
            </tr>
          </thead>
          <tbody>
            {Array.isArray(leaderboardData) && leaderboardData.length > 0 ? (
              leaderboardData.map((player, index) => (
                <tr key={player.id || index}>
                  <td>
                    <span className={`rank-badge rank-${index + 1}`}>
                      #{index + 1}
                    </span>
                  </td>
                  <td>
                    <div className="player-info">
                      <img 
                        src={player.avatar || '/default-avatar.png'} 
                        alt="Avatar" 
                        className="player-avatar"
                        onError={(e) => {
                          e.target.src = '/default-avatar.png';
                        }}
                      />
                      <span>{player.displayName}</span>
                    </div>
                  </td>
                  <td>
                    {activeTab === 'topPlayers' 
                      ? `${player.balance?.toLocaleString() || 0} AMP`
                      : activeTab === 'mostWins'
                        ? player.gamesWon || 0
                        : player.highestStreak || 0}
                  </td>
                  {activeTab !== 'highestStreak' && (
                    <>
                      <td>{player.gamesLost || 0}</td>
                      <td>{player.winRate ? `${player.winRate}%` : '0%'}</td>
                    </>
                  )}
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={activeTab === 'highestStreak' ? 3 : 5} style={{ textAlign: 'center' }}>
                  No data available
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    );
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="leaderboard-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Leaderboard</h2>
          <button className="close-modal" onClick={onClose}>×</button>
        </div>

        <div className="leaderboard-tabs">
          <button 
            className={`tab-btn ${activeTab === 'topPlayers' ? 'active' : ''}`}
            onClick={() => setActiveTab('topPlayers')}
          >
            Top Players
          </button>
          <button 
            className={`tab-btn ${activeTab === 'mostWins' ? 'active' : ''}`}
            onClick={() => setActiveTab('mostWins')}
          >
            Most Wins
          </button>
          <button 
            className={`tab-btn ${activeTab === 'highestStreak' ? 'active' : ''}`}
            onClick={() => setActiveTab('highestStreak')}
          >
            Highest Streak
          </button>
        </div>

        <div className="modal-body">
          {getTabContent()}
        </div>

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>
            Go Back
          </button>
        </div>
      </div>
    </div>
  );
};

export default LeaderboardModal;
